/* Select the strongest populated level separately for each required event house. */
(()=>{'use strict';const fields=method=>method==='sixfold'?['A','B','C','D','E','F']:['A','B','C','D'];function firstAvailable(row,method='fourfold'){for(const level of fields(method)){const planets=[...new Set((Array.isArray(row?.[level])?row[level]:[]).filter(id=>typeof id==='string'&&id))];if(planets.length)return {level,planets};}return {level:null,planets:[]};}function select(model,required,method='fourfold'){const data=model?.[method==='sixfold'?'sixfold':'fourfold'];const result=new Map();for(const house of [...new Set(required)]){const row=data?.houses?.find(r=>Number(r.id)===Number(house));if(!row)continue;const chosen=firstAvailable(row,method);for(const id of chosen.planets){if(!result.has(id))result.set(id,{id,houses:[],sourceHouses:[],levels:{}});const entry=result.get(id);entry.houses.push(Number(house));entry.sourceHouses.push(Number(house));entry.levels[house]=chosen.level;}}return [...result.values()].map(row=>({...row,houses:row.houses.sort((a,b)=>a-b),level:[...new Set(Object.values(row.levels))].join('/')}));}window.KPTransitSignificators=Object.freeze({firstAvailable,select});})();
